use std::error::Error;
use std::net::Ipv6Addr;

fn parse_both(addr: &str, port: &str) -> Result<(Ipv6Addr, u16), Box<dyn Error>> {
    let ip = addr.parse::<Ipv6Addr>()?;
    let port = port.parse::<u16>()?;
    Ok((ip, port))
}

fn main() {
    println!("{:?}", parse_both("::1", "8080"));
    println!("{}", parse_both("::1", "99999").unwrap_err());
    let e = parse_both("not-an-ip", "80").unwrap_err();
    println!("{e}");
    println!("is AddrParseError: {}", e.downcast_ref::<std::net::AddrParseError>().is_some());
}

