use std::error;
use std::fmt;
use std::fs::File;
use std::io;
use std::net::{self, Ipv6Addr};

#[derive(Debug)]
enum UpstreamError {
    IO(io::Error),
    Parsing(net::AddrParseError),
}

impl fmt::Display for UpstreamError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            UpstreamError::IO(e) => write!(f, "I/O error: {e}"),
            UpstreamError::Parsing(e) => write!(f, "bad address: {e}"),
        }
    }
}

impl error::Error for UpstreamError {
    fn source(&self) -> Option<&(dyn error::Error + 'static)> {
        match self {
            UpstreamError::IO(e) => Some(e),
            UpstreamError::Parsing(e) => Some(e),
        }
    }
}

impl From<io::Error> for UpstreamError {
    fn from(error: io::Error) -> Self {
        UpstreamError::IO(error)
    }
}

impl From<net::AddrParseError> for UpstreamError {
    fn from(error: net::AddrParseError) -> Self {
        UpstreamError::Parsing(error)
    }
}

fn connect(addr: &str, file: &str) -> Result<Ipv6Addr, UpstreamError> {
    let ip = addr.parse::<Ipv6Addr>()?;
    let _f = File::open(file)?;
    Ok(ip)
}

fn main() {
    for (addr, file) in [("zz", "x"), ("::1", "/no/such/file")] {
        match connect(addr, file) {
            Ok(ip) => println!("ok {ip}"),
            Err(UpstreamError::Parsing(_)) => println!("fix the address, please"),
            Err(e) => println!("{e} (source: {:?})", error::Error::source(&e).is_some()),
        }
    }
}

