#[derive(Debug)]
enum Thing {
    Sword,
    Trinket,
}

trait Enchanter: std::fmt::Debug {
    fn competency(&self) -> f64;

    // the book rolls a random die here; a fixed "roll" keeps the output repeatable
    fn enchant(&self, thing: &mut Thing, roll: f64) {
        let probability_of_success = self.competency();
        print!("{:?} mutters incoherently. ", self);
        if roll < probability_of_success {
            println!("The {:?} glows brightly.", thing);
        } else {
            println!("The {:?} fizzes, then turns into a worthless trinket.", thing);
            *thing = Thing::Trinket;
        }
    }
}

impl Enchanter for Dwarf {
    fn competency(&self) -> f64 {
        0.5
    }
}
impl Enchanter for Elf {
    fn competency(&self) -> f64 {
        0.95
    }
}
impl Enchanter for Human {
    fn competency(&self) -> f64 {
        0.8
    }
}

fn main() {
    let mut it = Thing::Sword;
    let d = Dwarf;
    let e = Elf;
    let h = Human;
    let party: Vec<&dyn Enchanter> = vec![&d, &h, &e];
    for (spellcaster, roll) in party.iter().zip([0.3, 0.9, 0.1]) {
        spellcaster.enchant(&mut it, roll);
    }
}

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq)]
struct MacAddress([u8; 6]);

impl fmt::Display for MacAddress {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let o = &self.0;
        write!(f, "{:02x}:{:02x}:{:02x}:{:02x}:{:02x}:{:02x}", o[0], o[1], o[2], o[3], o[4], o[5])
    }
}

impl MacAddress {
    /// A locally administered unicast address from 6 random bytes.
    fn local_unicast(mut octets: [u8; 6]) -> MacAddress {
        octets[0] |= 0b0000_0010; // local
        octets[0] &= !0b0000_0001; // unicast
        MacAddress(octets)
    }

    fn is_local(&self) -> bool {
        self.0[0] & 0b10 != 0
    }

    fn is_multicast(&self) -> bool {
        self.0[0] & 0b01 != 0
    }
}

fn main() {
    // bytes from a simple generator, so the output is repeatable
    let mut seed: u64 = 0x2545_F491_4F6C_DD1D;
    let mut octets = [0u8; 6];
    for b in octets.iter_mut() {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        *b = seed as u8;
    }
    let mac = MacAddress::local_unicast(octets);
    println!("mac: {mac} local={} multicast={}", mac.is_local(), mac.is_multicast());

    let broadcast = MacAddress([0xff; 6]);
    println!("{broadcast} local={} multicast={}", broadcast.is_local(), broadcast.is_multicast());
}

#[derive(Debug)]
enum State {
    Connecting { attempt: u32 },
    Sending(String),
    Waiting { sent: usize },
    Done(String),
    Failed(String),
}

// a pretend network: the first attempt fails, the second succeeds
fn try_connect(attempt: u32) -> bool {
    attempt >= 2
}

fn main() {
    let mut state = State::Connecting { attempt: 1 };
    loop {
        println!("{state:?}");
        state = match state {
            State::Connecting { attempt } if attempt > 3 => State::Failed(String::from("gave up")),
            State::Connecting { attempt } => {
                if try_connect(attempt) {
                    State::Sending(String::from("GET / HTTP/1.0\r\n\r\n"))
                } else {
                    State::Connecting { attempt: attempt + 1 }
                }
            }
            State::Sending(request) => State::Waiting { sent: request.len() },
            State::Waiting { sent } => State::Done(format!("200 OK after sending {sent} bytes")),
            State::Done(_) | State::Failed(_) => break,
        };
    }
}

